import re

from ta_moler.cmd.ru.genericru import Genericru
from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone


class Action(Genericru):
    """FrmonShellClient action command class."""

    def __init__(self, connection, action_name, agent_type, agent_instance_path, init_parameter, node="/",
                 prompt=None, newline_chars=None, runner=None):
        """
        Execute frmonShellClient action.

        :param connection: Moler connection to device, terminal when command is executed.
        :param action_name: Name of action to execute.
        :param agent_type: Agent type.
        :param agent_instance_path: Path to create node.
        :param init_parameter: Parameter to initialize agent.
        :param node: Node. Defaults to main dispatcher available on '/'.
        :param prompt: Prompt of the starting shell.
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command.
        """
        super(Action, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.node = node
        self.action_name = action_name
        self.agent_type = agent_type
        self.agent_instance_path = agent_instance_path
        self.init_parameter = init_parameter
        self.current_ret["STATUS"] = None

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        return f"{self.node} action {self.action_name} {self.agent_type} {self.agent_instance_path} " \
               f"{self.init_parameter}"

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise.
        :return: None
        """
        if is_full_line:
            try:
                self._command_error(line)
                self._parse_success_status(line)
            except ParsingDone:
                pass
        return super(Action, self).on_new_line(line, is_full_line)

    # action error
    _re_error = re.compile(r'(?P<CMD_ERROR>(error|failed))', re.I)

    def _command_error(self, line):
        if self._regex_helper.search_compiled(Action._re_error, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("CMD_ERROR")))
            raise ParsingDone

    # action done
    _re_done = re.compile(r'(?P<STATUS>==>\s*done\sok)', re.I)

    def _parse_success_status(self, line):
        if self._regex_helper.search_compiled(Action._re_done, line):
            self.current_ret["STATUS"] = "done"
            raise ParsingDone


